 if len(med)==3:
  out['comparisons'][phase].update({'optimized_change_vs_previous_percent':100*(med[labels[2]]/med[labels[0]]-1),'optimized_penalty_vs_protobuf_percent':100*(med[labels[2]]/med[labels[1]]-1),'paired_rounds':[{'round':rnd,'optimized_change_vs_previous_percent':100*(rr[labels[2]]/rr[labels[0]]-1),'optimized_penalty_vs_protobuf_percent':100*(rr[labels[2]]/rr[labels[1]]-1)} for rnd in [1,2,3] if len(rr:={r['implementation']:r[metric] for r in rows if r['round']==rnd})==3]})
 if phase=='production-java':continue
 groups={}; details={}; durations={}
 for r in rows:
  captures=[json.loads(s) for s in Path(r['metrics_path']).read_text().splitlines() if s.strip()]
  counter=collections.Counter(); times=collections.defaultdict(list)
  for c in captures:
   if c.get('elapsed_ms') is None:continue
   # Compare content and filenames, complete option order, and semantic config.
   # Normalize only generated roots and checkout/run roots; retain basename and source hash.
   def norm(s):
    s=str(s)
    roots={str(R):'$ROOT',c['stage_root']:'$STAGE',str(Path(c['stage_root'])/'clava'):'$CLAVA','/home/lmsousa/Documents/Projects/SPeCS/ast-flatbuffers/clava':'$CLAVA',str(Path(r['metrics_path']).parent/'source-overlays/protobuf'):'$CLAVA'}
    for root in sorted(roots,key=len,reverse=True):s=s.replace(root,roots[root])
    s=re.sub(r'\$ROOT/[^ ]*?/tmp(?:/|$)','$TMP/',s)
