    return s
   config={k:norm(v) for k,v in c.get('parser_config',{}).items() if k not in ['DUMPER_FOLDER','GENERATED_PARSE_ROOT','SHOW_EXEC_INFO','AST_DUMP_CACHE']}
   p={'sources':sorted((Path(x['path']).name,x['sha256']) for x in c['resolved_sources']),'options':[norm(v) for v in c['compiler_options']],'config':config}
   h=hashlib.sha256(json.dumps(p,sort_keys=True).encode()).hexdigest();counter[h]+=1;details[h]=p;times[h].append(c['elapsed_ms']/1000)
